select #{item.registBankCode,jdbcType=VARCHAR} REGIST_BANK_CODE, #{item.indentifyMark,jdbcType=VARCHAR} INDENTIFY_MARK, #{item.mergerindentifymark,jdbcType=VARCHAR} MERGER_INDENTIFY_MARK, #{item.prdRegistCode,jdbcType=VARCHAR} PRD_REGIST_CODE, #{item.holdDate,jdbcType=TIMESTAMP} HOLD_DATE, #{item.ccy,jdbcType=VARCHAR} CCY, #{item.amount,jdbcType=DECIMAL} AMOUNT, #{item.qty,jdbcType=DECIMAL} QTY, #{item.cnyAmt,jdbcType=DECIMAL} CNY_AMT, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.dataSource,jdbcType=CHAR} DATA_SOURCE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.operatestatus,jdbcType=VARCHAR} OPERATE_STATUS, #{item.workflowId,jdbcType=VARCHAR} WORKFLOW_ID, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.agent,jdbcType=VARCHAR} AGENT, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.prodid,jdbcType=VARCHAR} PRODID, #{item.interfCheckResult,jdbcType=VARCHAR} INTERF_CHECK_RESULT from dual
) A

