select #{item.registBankCode,jdbcType=VARCHAR} REGIST_BANK_CODE, #{item.indentifyMark,jdbcType=VARCHAR} INDENTIFY_MARK, #{item.prodid,jdbcType=VARCHAR} PRODID, #{item.holdDate,jdbcType=DATE} HOLD_DATE, #{item.ccy,jdbcType=VARCHAR} CCY, #{item.status,jdbcType=VARCHAR} STATUS, #{item.prdRegistCode,jdbcType=VARCHAR} PRD_REGIST_CODE, #{item.amount,jdbcType=DECIMAL} AMOUNT, #{item.qty,jdbcType=DECIMAL} QTY, #{item.cnyAmt,jdbcType=DECIMAL} CNY_AMT, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.dataSource,jdbcType=CHAR} DATA_SOURCE, #{item.workflowId,jdbcType=VARCHAR} WORKFLOW_ID, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, NOW(), #{item.createUser,jdbcType=VARCHAR} CREATE_USER, NOW(), #{item.agent,jdbcType=VARCHAR} AGENT, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.interfCheckResult,jdbcType=VARCHAR} INTERF_CHECK_RESULT from dual
) A
